Alias de Yaf_Loader::registerLocalNamespace.

  &reftitle.examples;

   Ejemplo de Yaf_Loader::registerNamespace


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initLoader()
    {
        /* registerNamespace() es un alias de registerLocalNamespace() */
        Yaf_Loader::getInstance()->registerNamespace(
            "Vendor",
            APPLICATION_PATH . "/library/Vendor"
        );
    }
}

/* new Vendor_Payment_Gateway() se busca ahora en
  * APPLICATION_PATH/library/Vendor/Payment/Gateway.php */
?>
